zeros = [(r,c) for r in range(23) for c in range(26) if inp2[r][c]==0]
# check diagonals slope -1: group by r+c
from collections import defaultdict
g1=defaultdict(list); g2=defaultdict(list)
for r,c in zeros: g1[r+c].append((r,c)); g2[r-c].append((r,c))
print("anti-diag (r+c) groups with >1:")
for k,v in sorted(g1.items()):
    if len(v)>1: print(k, sorted(v))
print("diag (r-c) groups:")
for k,v in sorted(g2.items()):
    if len(v)>1: print(k, sorted(v))
